def load_trace():
    raw=zlib.decompress(base64.b85decode(_DATA))
    assert len(raw)==836334 and hashlib.sha256(raw).hexdigest()=='6394373e959fe85c477c412424304e81f85e98166df49bca1f4bf23004368497'
    fixture=json.loads(raw);snapshots=fixture['snapshots']
    rows=[{'kind':'reset','snapshot':snapshots[0],'info':{'epoch':fixture['epoch']}}]
    for i,original in enumerate(fixture['infos']):
        info=copy.deepcopy(original);info['epoch']=fixture['epoch']
        info['command'].update(created_at=snapshots[i]['source_stamp'],expires_at=snapshots[i]['source_stamp']+2.)
        rows.append({'kind':'step','snapshot':snapshots[i+1],'info':info})
    return rows,fixture['diagnostics'],fixture['epoch']
